def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator row or column between equal-sized panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h // 2:
            n = r
            upper = grid[:n]
            lower = grid[r + 1:]
            if len(lower) == n:
                shared = set(x for row in upper for x in row) & set(
                    x for row in lower for x in row
                )
                fill = min(shared)
                return [
                    [3 if upper[i][j] == lower[i][j] else fill for j in range(w)]
                    for i in range(n)
                ]

    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and c == w // 2:
            n = c
            left = [row[:n] for row in grid]
            right = [row[c + 1:] for row in grid]
            if all(len(row) == n for row in left + right):
                shared = set(x for row in left for x in row) & set(
                    x for row in right for x in row
                )
                fill = min(shared)
                return [
                    [3 if left[i][j] == right[i][j] else fill for j in range(n)]
                    for i in range(h)
                ]

    return grid
